class NewsIngestionService:
    """Poll RSS/SEC-like feeds, persist raw items, and emit risk events."""

    def __init__(
        self,
        *,
        data_repo: DataRepository,
        agent_repo: AgentTaskRepository,
        strategy_repo: StrategyRepository,
        review_repo: ReviewRepository | None = None,
        client: httpx.Client | None = None,
    ) -> None:
        self.data_repo = data_repo
        self.agent_repo = agent_repo
        self.strategy_repo = strategy_repo
        self.review_repo = review_repo
        self.client = client

    def poll_configured_feeds(self) -> dict[str, Any]:
        urls = {
            "jinshi": settings.jinshi_rss_url,
            "coindesk": settings.coindesk_rss_url,
            "theblock": settings.theblock_rss_url,
            "reuters_crypto": settings.reuters_crypto_rss_url,
            "sec_edgar": settings.sec_edgar_rss_url,
        }
        captured = 0
        risk_events = 0
        disabled = []
        for source, url in urls.items():
            if not url:
                disabled.append(source)
                continue
            items = self.fetch_feed(source=source, url=url)
            for item in items:
                captured += 1
                stored = self.data_repo.store_news_item(item)
                if _is_relevant(item):
                    event = self._classify_and_emit(item)
                    if event is not None:
                        risk_events += 1
                        self.data_repo.store_news_item(
                            {
                                **stored,
                                "id": stored["id"],
                                "severity": str(event.severity),
                                "sentiment": _directional_sentiment(item),
                                "relevance_status": "risk_event_emitted",
                                "affected_symbols": event.affected_scope,
                            }
                        )
        return {"captured": captured, "risk_events": risk_events, "disabled_sources": disabled}

    def fetch_feed(self, *, source: str, url: str) -> list[dict[str, Any]]:
        close_client = self.client is None
        client = self.client or httpx.Client(timeout=10.0, follow_redirects=True)
        try:
            response = client.get(url, headers={"user-agent": "ai-quant-research-platform/0.1"})
            response.raise_for_status()
            return _parse_rss(source=source, body=response.text)
        finally:
            if close_client:
                client.close()

    def _classify_and_emit(self, item: dict[str, Any]) -> RiskEvent | None:
        task = AgentTaskService(
            agent_repo=self.agent_repo,
            strategy_repo=self.strategy_repo,
            review_repo=self.review_repo,
            llm_runtime=_configured_llm_runtime(),
        ).submit_task(
            AgentTaskRequest(
                agent_type="news_agent",
                task_type="classify_event",
                input_ref=f"news_item:{item['id']}",
                input_payload=item,
            )
        )
        classification = task.output_payload.get("classification") or {}
        severity = _normalize_severity(classification.get("severity") or _keyword_severity(item))
        if severity in {RiskSeverity.HIGH, RiskSeverity.CRITICAL}:
            return self.data_repo.store_risk_event(
                RiskEvent(
                    event_type=RiskEventType.NEWS_RISK,
                    severity=severity,
                    source=str(item.get("source", "news")),
                    description=str(classification.get("summary") or item.get("title") or "news risk event"),
                    affected_scope=["BTC/USDT"],
                    recommended_action="pause_strategy",
                    occurred_at=datetime.now(UTC),
                    expires_at=datetime.now(UTC) + timedelta(minutes=settings.news_high_severity_pause_minutes),
                )
            )
        return None


def _parse_rss(*, source: str, body: str) -> list[dict[str, Any]]:
    root = ET.fromstring(body)
    nodes = root.findall(".//item") or root.findall(".//{http://www.w3.org/2005/Atom}entry")
    items = []
    for node in nodes[:50]:
        title = _child_text(node, "title")
        url = _child_text(node, "link")
        if not url:
            link_node = node.find("{http://www.w3.org/2005/Atom}link")
            url = link_node.attrib.get("href", "") if link_node is not None else ""
        summary = _child_text(node, "description") or _child_text(node, "{http://www.w3.org/2005/Atom}summary")
        published = _parse_date(
            _child_text(node, "pubDate")
            or _child_text(node, "published")
            or _child_text(node, "{http://www.w3.org/2005/Atom}updated")
        )
        digest = hashlib.sha256(f"{source}:{url or title}".encode("utf-8")).hexdigest()[:32]
        items.append(
            {
                "id": digest,
                "source": source,
                "title": title or "untitled",
                "url": url or None,
                "summary": summary,
                "published_at": published,
                "raw_payload": {"source": source},
                "relevance_status": "captured",
            }
        )
    return items


def _child_text(node: ET.Element, name: str) -> str:
    child = node.find(name)
    if child is None:
        child = node.find(f"{{http://www.w3.org/2005/Atom}}{name}")
    return (child.text or "").strip() if child is not None else ""


def _parse_date(value: str) -> datetime:
    if not value:
        return datetime.now(UTC)
    parsed = parsedate_to_datetime(value)
    return parsed if parsed.tzinfo is not None else parsed.replace(tzinfo=UTC)


def _is_relevant(item: dict[str, Any]) -> bool:
    text = f"{item.get('title', '')} {item.get('summary', '')}".lower()
    return any(keyword in text for keyword in HIGH_KEYWORDS)


def _keyword_severity(item: dict[str, Any]) -> str:
    text = f"{item.get('title', '')} {item.get('summary', '')}".lower()
    if any(keyword in text for keyword in {"hack", "exploit", "bankruptcy", "depeg", "暴雷", "脱锚"}):
        return "critical"
    if _is_relevant(item):
        return "high"
    return "low"


def _directional_sentiment(item: dict[str, Any]) -> str:
    text = f"{item.get('title', '')} {item.get('summary', '')}".lower()
    if any(word in text for word in {"approval", "approved", "inflow", "降息", "批准"}):
        return "positive"
    if any(word in text for word in {"hack", "lawsuit", "outflow", "清算", "暴雷"}):
        return "negative"
    return "neutral"


def _normalize_severity(value: object) -> RiskSeverity:
    normalized = str(value or "low").lower().replace("medium", "mid")
    try:
        return RiskSeverity(normalized)
    except ValueError:
        return RiskSeverity.LOW


def _configured_llm_runtime():
    if not settings.claude_api_key:
        return UnavailableLLMRuntime()
    return ConfiguredStructuredLLMRuntime(
        anthropic_api_key=settings.claude_api_key,
        default_model=settings.claude_model,
        anthropic_base_url=settings.anthropic_api_base_url,
        provider_by_agent={},
        model_by_agent={},
    )

"""B-level macro calendar ingestion and planned risk windows."""

from __future__ import annotations

import xml.etree.ElementTree as ET
from datetime import UTC, datetime, timedelta
from email.utils import parsedate_to_datetime
from typing import Any

import httpx

from apps.api.config import settings
from services.data.repository import DataRepository
from shared.models import RiskEvent, RiskEventType, RiskSeverity

HIGH_IMPACT_TERMS = {"fomc", "cpi", "ppi", "nonfarm", "nfp", "fed", "interest rate", "gdp", "pmi"}


class MacroCalendarService:
    """Persist macro events and create pause windows for high-impact items."""

    def __init__(self, *, data_repo: DataRepository, client: httpx.Client | None = None) -> None:
        self.data_repo = data_repo
        self.client = client

    def poll_configured_sources(self) -> dict[str, Any]:
        if not settings.forexfactory_rss_url and not settings.trading_economics_api_key:
            return {"captured": 0, "risk_events": 0, "disabled": True}
        captured = 0
        risk_events = 0
        if settings.forexfactory_rss_url:
            for event in self.fetch_forexfactory_rss(settings.forexfactory_rss_url):
                captured += 1
                stored = self.data_repo.store_macro_event(event)
                if self._within_pause_window(stored) and str(stored.get("impact")) in {"high", "critical"}:
                    self.data_repo.store_risk_event(
                        RiskEvent(
                            event_type=RiskEventType.MACRO_EVENT,
                            severity=RiskSeverity.HIGH,
                            source="macro_calendar",
                            description=f"Macro event window: {stored['event_name']}",
                            affected_scope=stored.get("affected_symbols") or ["BTC/USDT"],
                            recommended_action="pause_strategy",
                            occurred_at=datetime.now(UTC),
                            expires_at=_parse_datetime(stored["scheduled_at"])
                            + timedelta(minutes=settings.macro_event_pause_after_minutes),
                        )
                    )
                    risk_events += 1
        return {"captured": captured, "risk_events": risk_events, "disabled": False}

    def fetch_forexfactory_rss(self, url: str) -> list[dict[str, Any]]:
        close_client = self.client is None
        client = self.client or httpx.Client(timeout=10.0, follow_redirects=True)
        try:
            response = client.get(url, headers={"user-agent": "ai-quant-research-platform/0.1"})
            response.raise_for_status()
            return _parse_macro_rss(response.text)
        finally:
            if close_client:
                client.close()

    @staticmethod
    def _within_pause_window(event: dict[str, Any]) -> bool:
        scheduled_at = _parse_datetime(event["scheduled_at"])
        now = datetime.now(UTC)
        return scheduled_at - timedelta(minutes=settings.macro_event_pause_before_minutes) <= now <= (
            scheduled_at + timedelta(minutes=settings.macro_event_pause_after_minutes)
        )


def _parse_macro_rss(body: str) -> list[dict[str, Any]]:
    root = ET.fromstring(body)
    events = []
    for node in root.findall(".//item")[:50]:
        title = _text(node, "title") or "macro event"
        scheduled_at = _parse_rss_date(_text(node, "pubDate"))
        impact = "high" if any(term in title.lower() for term in HIGH_IMPACT_TERMS) else "low"
        events.append(
            {
                "event_name": title[:80],
                "source": "forexfactory",
                "impact": impact,
                "scheduled_at": scheduled_at,
                "affected_symbols": ["BTC/USDT"] if impact == "high" else None,
                "notes": _text(node, "description"),
            }
        )
    return events


def _text(node: ET.Element, name: str) -> str:
    child = node.find(name)
    return (child.text or "").strip() if child is not None else ""


def _parse_rss_date(value: str) -> datetime:
    if not value:
        return datetime.now(UTC)
    parsed = parsedate_to_datetime(value)
    return parsed if parsed.tzinfo is not None else parsed.replace(tzinfo=UTC)


def _parse_datetime(value: str | datetime) -> datetime:
    if isinstance(value, datetime):
        return value if value.tzinfo is not None else value.replace(tzinfo=UTC)
    parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    return parsed if parsed.tzinfo is not None else parsed.replace(tzinfo=UTC)

