            response = client.get(
                f"https://api.twitter.com/2/users/{user_id}/tweets",
                headers={"authorization": f"Bearer {settings.twitter_bearer_token}"},
                params={"max_results": 5, "tweet.fields": "created_at"},
            )
            response.raise_for_status()
            payload = response.json()
        finally:
            if close_client:
                client.close()
        return [
